"""Thin wrapper around the authors' fastText engine.

The paper's system *is* the authors' C++ fastText supervised trainer
(https://github.com/facebookresearch/fastText, v0.9.2 -- the same version as
the cloned `repo/`).  This module only locates a usable build of that exact
code and forwards every argument verbatim; no author code is rewritten.

Engine preference order:
  1. an importable `fasttext` module (fasttext-wheel 0.9.2 ships the authors'
     unmodified C++ sources as a prebuilt wheel -- used on this Windows host,
     where no C++ toolchain / make is available);
  2. `pip install fasttext-wheel` (same prebuilt wheel);
  3. a native build of the cloned repo (`make` or `pip install .`);
  4. the authors' PyTorch EmbeddingBag example
     (python/doc/examples/FastTextEmbeddingBag.py) -- a re-implementation, so
     the run is then flagged `partially_reproduced`.
"""
import importlib
import os
import subprocess
import sys

import config

ENGINE = None
ENGINE_DETAIL = {}
VERDICT_CEILING = "reproduced"


def _try_import():
    try:
        mod = importlib.import_module("fasttext")
    except Exception:
        return None
    if not hasattr(mod, "train_supervised"):
        return None
    return mod


def _pip_install_fasttext_wheel():
    try:
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", "fasttext-wheel==0.9.2"],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    except Exception:
        return None
    return _try_import()


def _native_build():
    """Build the cloned repo with make / pip if a POSIX toolchain exists."""
    repo = os.path.join(config.ROOT, "repo")
    if not os.path.isdir(repo):
        return None
    for cmd in (["make", "-C", repo], [sys.executable, "-m", "pip", "install", repo]):
        try:
            subprocess.check_call(cmd, stdout=subprocess.DEVNULL,
                                  stderr=subprocess.DEVNULL, timeout=600)
        except Exception:
            continue
        mod = _try_import()
        if mod is not None:
            return mod
    return None


def load_engine(verbose=True):
    """Return (module, provenance-dict)."""
    global ENGINE, ENGINE_DETAIL, VERDICT_CEILING

    mod = _try_import()
    if mod is not None:
        ENGINE = mod
        ENGINE_DETAIL = {
            "engine": "fasttext-wheel (prebuilt wheel of the authors' "
                      "fastText 0.9.2 C++ sources)",
            "engine_kind": "authors_code",
            "module_file": getattr(mod, "__file__", None),
        }
        VERDICT_CEILING = "reproduced"
        if verbose:
            print("[engine] using existing `import fasttext` -> %s"
                  % ENGINE_DETAIL["module_file"], flush=True)
        return ENGINE, ENGINE_DETAIL

    mod = _pip_install_fasttext_wheel()
    if mod is not None:
        ENGINE = mod
        ENGINE_DETAIL = {
            "engine": "fasttext-wheel 0.9.2 installed by reproduce.py "
                      "(prebuilt wheel of the authors' fastText 0.9.2 C++ sources)",
            "engine_kind": "authors_code",
            "module_file": getattr(mod, "__file__", None),
        }
        VERDICT_CEILING = "reproduced"
        if verbose:
            print("[engine] installed fasttext-wheel 0.9.2", flush=True)
        return ENGINE, ENGINE_DETAIL

    mod = _native_build()
    if mod is not None:
        ENGINE = mod
        ENGINE_DETAIL = {
            "engine": "native build of the cloned facebookresearch/fastText repo",
            "engine_kind": "authors_code",
            "module_file": getattr(mod, "__file__", None),
        }
        VERDICT_CEILING = "reproduced"
        if verbose:
            print("[engine] native build of repo/", flush=True)
        return ENGINE, ENGINE_DETAIL

    ENGINE = None
    ENGINE_DETAIL = {
        "engine": "UNAVAILABLE",
        "engine_kind": "none",
    }
    VERDICT_CEILING = "blocked"
    raise RuntimeError(
        "No fastText engine available: `import fasttext` failed, "
        "`pip install fasttext-wheel` failed and no POSIX toolchain was found "
        "to build repo/."
    )


def train(input_path, output_path, verbose=2, **kwargs):
    """Train with the authors' supervised trainer; returns the model object."""
    if ENGINE is None:
        load_engine()
    params = dict(kwargs)
    params["input"] = input_path
    if verbose is not None:
        params["verbose"] = verbose
    model = ENGINE.train_supervised(**params)
    if output_path:
        model.save_model(output_path + ".bin")
    return model


def test(model, path):
    """Return (N, precision@1, recall@1) exactly as `./fasttext test` reports."""
    return model.test(path)

